has_default_in_chain(node) := result {
    # Build the chain of else_statements
    chain := chain_nodes(node)
    # Check if any node in the chain is a default
    result := count([n | n := chain[_]; n.is_default == true]) > 0
}

# Helper rule to build the chain of else_statements
chain_nodes(node) := chain {
    chain := {n | n := traverse_else(node, 0)}
}

# Helper function to traverse else_statements iteratively using recursion with depth limit
